import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";

if (!existsSync(".env.qa")) throw new Error("No test backend: run `npm run setup -- --qa` first");
process.loadEnvFile(".env.qa");
const flags = ["RESERVATION", "IMPORT_EXCLUSION", "IMPORT_ROW_UNDO", "VERIFIED_EVIDENCE", "INVESTIGATION_REQUEST", "DATA_QUERY", "OWN_TRANSFERS", "SCHEMA"];
